#define res (80.+sin(iTime*.2)*20.)


vec2 random2(vec2 p) {
    return fract(sin(vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)))) * 43758.5453);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
    {
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    vec4 color = vec4(0.0);

    vec2 m_neigh,m_diff;

    float resol = res;

    vec2 uvS = uv*resol;
    vec2 iPos = floor(uvS);
    vec2 iPos2 = iPos / resol;
    vec2 fPos = fract(uvS);
    vec2 fPos2 = fPos /resol;

    float m_dist = 8.0;
    vec4 point_color;
    vec4 m_point;        // minimum point   

    for(int y = -1; y <= 1; y++) {
        for(int x = -1; x <= 1; x++) {
            vec2 neighbor = vec2(float(x), float(y));
            vec2 point = vec2(.5);
            point = random2(iPos + neighbor);
            point_color = texture(iChannel0,iPos2+neighbor/resol);
            //point = 0.5 + 0.5 * sin(iTime + 6.2831 * point);
            vec2 diff = neighbor + point - fPos;
            float dist = dot(diff,diff);
            if(dist < m_dist) {
                m_dist = dist;
                m_neigh=neighbor;
                m_diff = diff;
                m_point = point_color;
            }
        }
    }

    m_dist = 8.0;

    for(int y = -2; y <= 2; y++) {
        for(int x = -2; x <= 2; x++) {
            vec2 neighbor = m_neigh + vec2(float(x), float(y));
            vec2 point = vec2(.5);
            point = random2(iPos + neighbor);
            //point = 0.5 + 0.5 * sin(iTime + 6.2831 * point);
            vec2 diff = neighbor + point - fPos;

            if(dot(m_diff-diff,m_diff-diff)>0.00001)
            m_dist = min(m_dist,dot(0.5*(m_diff+diff),normalize(diff-m_diff)));

        }
    }
    // Output to screen
    //color = texture(iChannel0,uv);
    //color = texture(iChannel0,iPos);
    color = vec4(m_point.rgb,0.5);
    color = mix( vec4(0.576, 0.831, 0.82,1.0), color, smoothstep(.04,0.041, m_dist) );

        //color += 1. - smoothstep(.01,0.02, m_dist);
    fragColor = vec4(color);
}
